let E=EDITIONS.tokyo,PRICE_BREAKS,COUNT_BREAKS;
const isLand=()=>E.landType!=null&&state.type===E.landType,priceBreaks=()=>isLand()&&E.landBreaks?E.landBreaks:state.unit==='home'?E.homeBreaks:PRICE_BREAKS;const GROWTH_BREAKS=[-20,0,25,50,100],RANK_MIN=30,FULL_MIN=10,EMPTY=[0,null,null,null,null,null,null];
// Source records across the apartment and house-and-land extracts of the shown prefectures.
const japanRecords=()=>Object.keys(D.prefectures).reduce((a,c)=>a+D.coverage[c].raw+Object.values((D.type_coverage||{})[c]||{}).reduce((x,y)=>x+y.raw,0),0);
// Japanese prices per home read in 万円, as Japanese listings give them (3,950万円; 1億2,000万円).
const MAN=()=>JA&&E.ja&&PH(),man=v=>{const m=Math.round(v/1e4),o=Math.floor(m/1e4),r=m%1e4;return o?`${o}億${r?fmt(r)+'万':''}円`:`${fmt(m)}万円`};
const money=v=>v==null?'—':MAN()?man(v):E.cur+fmt(v);
// Per m² everywhere except pages priced per home (Scotland), where the unit is dropped.
// Prices per home (Phil, 2026-10-29): where a map has them (D.homes, and homeBreaks in its settings), a switch beside the
// map colours shows the median total price instead of the price per m². They load from homes-N.json when first chosen and
// carry their own windows (the UK's run on to 2024–25, from every Land Registry sale); the UK's have no size or era bands.
const HOMES=()=>!!(D&&D.homes&&E.homeBreaks),PH=()=>E.perHome||state.unit==='home',noBands=()=>state.unit==='home'&&!D.homes.bands,
  noArea=()=>E.perHome||state.unit==='home'&&!D.homes.area,HX=k=>state.unit==='home'&&E.homeX&&k in E.homeX?E.homeX[k]:E[k];
const UE=()=>PH()?'':'/m²',UJ=()=>PH()?'':'/㎡';
