const css=n=>getComputedStyle(document.documentElement).getPropertyValue(n).trim(), isDark=()=>getComputedStyle(document.documentElement).colorScheme==='dark';
const step=(v,breaks)=>breaks.filter(b=>v>=b).length;
// Cells with fewer than 5 sales are stored as a bare count; a median from 5–9 sales is indicative and has no quartiles.
const thin=c=>c[1]!=null&&c[0]<FULL_MIN;
function cell(s,p=state.period){const c=(state.unit==='home'?s.hcells||{}:s.cells)[E.dims.reduce((k,d)=>k+'-'+state[d],p)];return c==null?EMPTY:typeof c==='number'?[c]:c}
function growth(s){const a=cell(s),b=cell(s,state.baseline);return a[0]>=20&&b[0]>=20&&b[1]>0?(a[1]/b[1]-1)*100:null}
