const prefMatch=code=>{if(!state.pref||state.pref===code)return true;const g=(D.pref_groups||{})[code];return !!g&&(state.pref==='g:'+g||(!!E.outer&&state.pref==='g:'+E.outer[1]&&g!==E.outer[0]))},prefName=code=>code.startsWith('g:')?code.slice(2):D.prefectures[code];
