// Price history chart; numbered event markers sit on the two-year window that contains each event.
function drawChart(series,events=[]){const W=290,H=165,left=38,top=16,bottom=140,right=280;let values=series.flatMap(s=>D.periods.map((_,p)=>cell(D.stations[s],p)[1]).filter(x=>x!=null));if(!values.length)return `<p class="muted">${J('Not enough observations for a price history with these filters.','この条件では価格の推移を示すだけの取引がない。')}</p>`;const last=D.periods.length-1;let max=Math.ceil(Math.max(...values)/HX('chartStep'))*HX('chartStep')||HX('chartStep');const x=p=>left+p*(right-left)/last,y=v=>bottom-(v/max)*(bottom-top);let html=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${J(`Median price history in ${T(HX('chartAria'))}${PH()?' per home':' per square metre'}`,`中央値の推移（${T(HX('chartAria'))}${PH()?'/戸':'/㎡'}）`)}"><rect class="current" x="${x(state.period)-10}" y="${top}" width="20" height="${bottom-top}"/>`;for(let k=0;k<=3;k++){let v=max*k/3;html+=`<line class="grid" x1="${left}" x2="${right}" y1="${y(v)}" y2="${y(v)}"/><text x="${left-5}" y="${y(v)+3}" text-anchor="end">${(v/HX('chartDiv')).toFixed(0)}</text>`}[0,4,last].forEach(p=>html+=`<text x="${x(p)}" y="157" text-anchor="middle">${D.periods[p].slice(0,4)}</text>`);
const tiers={};events.forEach(([m,te,,tj],k)=>{const t=JN()&&tj?tj:te;const p=Math.floor((+m.slice(0,4)-2006)/2);if(p<0||p>last)return;const ty=1+(tiers[p]=(tiers[p]||0)+1)*13-13;html+=`<line class="evline" x1="${x(p)}" x2="${x(p)}" y1="${top}" y2="${bottom}"/><g><rect class="evtag" x="${x(p)-6}" y="${ty}" width="12" height="12"/><text class="evtxt" x="${x(p)}" y="${ty+9}" text-anchor="middle">${k+1}</text><title>${esc(t)} · ${monYear(m)}</title></g>`});
series.forEach((idx,j)=>{let path='',open=false;D.periods.forEach((period,p)=>{let c=cell(D.stations[idx],p);if(c[1]==null){open=false;return}path+=`${open?'L':'M'}${x(p)},${y(c[1])} `;open=true});html+=`<path class="series" stroke="${colours[j]}" d="${path}"/>`;D.periods.forEach((period,p)=>{let c=cell(D.stations[idx],p);if(c[1]!=null)html+=`<circle${thin(c)?` class="ind" style="stroke:${colours[j]}"`:''} fill="${colours[j]}" cx="${x(p)}" cy="${y(c[1])}" r="3.5"><title>${esc(nm(D.stations[idx]))} · ${period}: ${money(c[1])}${UE()}${thin(c)?J(' (indicative)','（参考値）'):''} · ${J(`${fmt(c[0])} sales`,`${fmt(c[0])}件`)}</title></circle>`})});return html+'</svg>'}
const eventsKey=ev=>ev.length?`<p class="events">${ev.map(([m,te,src,tj],k)=>`<span class="ev">${k+1}</span>${esc(JN()&&tj?tj:te)}${J(', ','、')}${monYear(m)} (<a href="${esc(src)}" target="_blank" rel="noopener">${J('source','出典')}</a>)`).join(' · ')}</p>`:'';
