const stationRows=idx=>[[J('Period','期間'),J('Sales','取引件数'),J(`Median ${E.cur}${UE()}`,`中央値 ${E.cur}${UJ()}`),J(`Lower quartile ${E.cur}${UE()}`,`第1四分位 ${E.cur}${UJ()}`),J(`Upper quartile ${E.cur}${UE()}`,`第3四分位 ${E.cur}${UJ()}`),isLand()?J('Median plot area m²','土地面積の中央値 ㎡'):J('Median floor area m²','床面積の中央値 ㎡'),T(E.stats[0][2]),T(E.stats[1][2]),J('Indicative (under 10 sales)','参考値（10件未満）')],...D.periods.map((p,i)=>{const c=cell(D.stations[idx],i);return [p,c[0],c[1],c[2],c[3],c[4],c[5],c[6],thin(c)?J('yes','はい'):'']})].map(r=>noArea()?r.filter((_,k)=>k!==5):r);
