function unitSwitch(){const f=document.createElement('div');f.className='field';f.innerHTML=`<span class="fieldlabel" id="unitName"><span class="l-en">Prices</span><span class="l-ja">価格の単位</span></span><div class="seg" id="unit" role="group" aria-labelledby="unitName"><button type="button" data-v="m2"><span class="l-en">Per m²</span><span class="l-ja">㎡単価</span></button><button type="button" data-v="home"><span class="l-en">Per home</span><span class="l-ja">1戸あたり</span></button></div>`;$('metric').closest('.field').after(f);
  $('metric').querySelector('[data-v=price]').innerHTML='<span class="l-en">Price</span><span class="l-ja">価格</span>';f.querySelectorAll('button').forEach(b=>b.onclick=()=>setUnit(b.dataset.v));
  const n=document.createElement('section');n.id='homesNote';n.innerHTML=D.homes.bands?`<div class="l-en"><h3>Prices per home</h3><p>The Per home switch shows the median total price of the homes sold instead of the price per m². It is what buyers pay, but it mixes location with size: stations where small apartments sell look cheaper per home than per m², and those where large houses sell look dearer. It uses the same sales and filters as the price per m²; land is priced per m² only.</p></div><div class="l-ja"><h3>1戸あたりの価格</h3><p>「1戸あたり」に切り替えると、㎡単価の代わりに取引された住宅の総額の中央値を示す。買い手が実際に払う額だが、立地と広さが混ざる。小さな住戸が多く売れる駅は㎡単価で見るより安く、大きな戸建てが多い駅は高く見える。㎡単価と同じ取引と絞り込みを使う。土地は㎡単価のみである。</p></div>`:`<div class="l-en"><h3>Prices per home</h3><p>The Per home switch shows the median total price of the homes sold instead of the price per m². It is what buyers pay, but it mixes location with size: stations where small flats sell look cheaper per home than per m², and those where large houses sell look dearer. It uses every Land Registry standard sale, with or without an energy certificate, so its samples are larger and it runs to ${D.homes.periods[D.homes.periods.length-1]}; the size and era filters do not apply, as floor areas and ages come from the certificates.</p></div><div class="l-ja"><h3>1戸あたりの価格</h3><p>「1戸あたり」に切り替えると、㎡単価の代わりに取引された住宅の総額の中央値を示す。買い手が実際に払う額だが、立地と広さが混ざる。小さなフラットが多く売れる駅は㎡単価で見るより安く、大きな住宅が多い駅は高く見える。エネルギー証明書の有無にかかわらず土地登記所の標準取引をすべて使うため、件数が多く、${D.homes.periods[D.homes.periods.length-1]}年まで示す。床面積と建築年代は証明書から取るので、広さと年代の絞り込みは使えない。</p></div>`;$('analyticsNote').before(n)}
async function setUnit(u){if(u===state.unit||u==='home'&&isLand())return;state.unit=u;if(noBands()){state.size=0;state.age=0}usePeriods();track('change_unit',{unit:u});await ensureCells();syncControls();render();changed()}
async function ensureCells(){if(state.unit==='home'){const f=D.homes.split?state.type:0;if(loadedCells['h'+f])return;const {keys,rows}=await getJSON(`homes-${f}.json`);rows.forEach((c,i)=>{const s=D.stations[i];s.hcells=Object.assign(s.hcells||{},unpackCells(keys,c))});loadedCells['h'+f]=true;return}const f=state.type?state.type:state.size||state.age?0:null;if(f==null||loadedCells[f])return;const {keys,rows}=await getJSON(`cells-${f}.json`);rows.forEach((c,i)=>Object.assign(D.stations[i].cells,unpackCells(keys,c)));loadedCells[f]=true}
// Each deploy stamps ?v= on the script URL; data URLs carry the same stamp and are revalidated on every load, so a
// visitor never pairs a cached script with newer data. DATA_FORMAT changes whenever the data's shape does.
const VERSION=(document.currentScript&&new URL(document.currentScript.src).searchParams.get('v'))||'',DATA_FORMAT=6;
// Files stamped at deploy are new at every build, so the browser may keep them; a local build's literal BUILD stamp always asks.
async function getJSON(p){const r=await fetch(VERSION?`${p}?v=${VERSION}`:p,VERSION&&VERSION!=='BUILD'?{}:{cache:'no-cache'});if(!r.ok)throw Error(J(`Could not load ${p}`,`${p} を読み込めなかった`));return r.json()}
