// Rankings sort by any column; price rankings need 30 sales, change needs 20 in both windows.
function rankingRows(){const key=state.sortKey,dir=state.sortDir;let ss=D.stations.map((s,i)=>({s,i,c:cell(s),g:growth(s)})).filter(x=>visible(x.s));
ss=ss.filter({price:x=>x.c[0]>=RANK_MIN,change:x=>x.g!=null,sales:x=>x.c[0]>0}[key]||(x=>x.c[1]!=null));
const val={name:x=>nm(x.s).toLowerCase(),pref:x=>prefLabel(x.s.pref)+' '+nm(x.s).toLowerCase(),price:x=>x.c[1],change:x=>x.g,sales:x=>x.c[0]}[key];return ss.sort((a,b)=>{const A=val(a),B=val(b);return (A>B?1:A<B?-1:0)*dir})}
