// English matches ignore macrons, hyphens and spaces, so "omiya" finds Ōmiya and "shinyokohama" finds Shin-Yokohama.
function search(){const q=$('search').value.trim(),f=fold(q);if(!q){$('results').innerHTML='';return}const hit=s=>s.name.includes(q)||(f&&fold(label(s)).includes(f))||s.lines.some(l=>l.includes(q)||(f&&fold(lineEn(l)[0]).includes(f)));const pre=s=>Boolean((f&&fold(label(s)).startsWith(f))||s.name.startsWith(q));const hits=D.stations.map((s,i)=>({s,i})).filter(({s})=>hit(s)).sort((a,b)=>pre(b.s)-pre(a.s)).slice(0,15);$('results').innerHTML=hits.length?hits.map(({s,i})=>`<button data-result="${i}">${both(s)} <small>${esc(prefLabel(s.pref))}</small></button>`).join(''):`<p class="muted">${E.ja?J('No matches. Try the English or Japanese station name.','一致する駅がない。日本語か英語の駅名で検索。'):J('No matches. Try a station or line name.','一致する駅がない。駅名か路線名で検索。')}</p>`;document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const idx=+b.dataset.result;track('search',{search_term:$('search').value.trim()});state.pref='';state.line='';$('pref').value='';$('line').value='';render();pickStation(idx,true);$('results').innerHTML='';$('search').value=nm(D.stations[idx])})}

// The area and line menus are rebuilt when the language changes; their values, and the slugs in links, stay the same.
const OUTER_JA={'Commuter belt':'通勤圏'};
function buildSelects(){const clear=sel=>{const v=sel.value;while(sel.options.length>1)sel.remove(1);sel.querySelectorAll('optgroup').forEach(g=>g.remove());return v};
const pv=clear($('pref')),lv=clear($('line')),cmp=(a,b)=>a.localeCompare(b,JA?'ja':'en');
const prefs=Object.entries(D.prefectures).sort((a,b)=>E.ja?a[0].localeCompare(b[0]):cmp(a[1],b[1]));
if(D.pref_groups){const core=E.outer&&E.outer[0],groups=[...new Set(Object.values(D.pref_groups))].sort((a,b)=>(b===core)-(a===core)||a.localeCompare(b));(E.outer||[]).forEach(g=>$('pref').add(new Option(J(`${g} (all)`,`${OUTER_JA[g]||g}（全域）`),'g:'+g)));
for(const g of groups){const og=document.createElement('optgroup');og.label=g;if(g!==core)og.append(new Option(J(`All of ${g}`,`${g} 全域`),'g:'+g));prefs.filter(([c])=>D.pref_groups[c]===g).forEach(([c,n])=>og.append(new Option(n,c)));$('pref').append(og)}}
else for(const [code] of prefs)$('pref').add(new Option(prefLabel(code),code));
const byOperator={};for(const l of new Set(D.stations.flatMap(s=>s.lines))){const [ln,op]=lineLabel(l);(byOperator[op]||=[]).push([ln,l])}
if(E.ja){const g=document.createElement('optgroup');g.label=J('Line groups','路線グループ');for(const [k,en,ja] of LINE_GROUPS)if(Object.values(LINE_GROUP).includes(k))g.append(new Option(J(en,ja),k));$('line').append(g)}
for(const op of Object.keys(byOperator).sort(cmp)){const g=document.createElement('optgroup');g.label=op;byOperator[op].sort((a,b)=>cmp(a[0],b[0])).forEach(([ln,l])=>g.append(new Option(ln,l)));$('line').append(g)}
$('pref').value=pv;$('line').value=lv}
