const cityAt=ll=>{let best=null,bd=Infinity;for(const c of E.cities||[]){const b=L.latLngBounds(c.box);if(!b.contains(ll))continue;const d=b.getCenter().distanceTo(ll);if(d<bd){bd=d;best=c}}return best};
